:root { --sidebar-width: 240px; }
.sidebar {
  position: fixed; top: 0; left: 0; bottom: 0;
  width: var(--sidebar-width);
  background: #0f172a; color: #fff;
}
.content { margin-left: calc(var(--sidebar-width) + 16px); }   /* 240px + 16px = 256px */

